export function Carousel({ carousel }: ComponentProps) {
    const { slides, currentIndex, globalIndex } = useLightboxState();
    const { setCarouselRef } = useController();

    const spacingValue = parseLengthPercentage(carousel.spacing);
    const paddingValue = parseLengthPercentage(carousel.padding);

    const items = [];
    const preload = Math.min(carousel.preload, Math.max(Math.floor(slides.length / 2), 1));

    if (hasSlides(slides)) {
        for (let i = currentIndex - preload; i < currentIndex; i += 1) {
            const key = globalIndex + i - currentIndex;
            items.push(
                !carousel.finite || i >= 0 ? (
                    <CarouselSlide
                        key={key}
                        slide={slides[(i + preload * slides.length) % slides.length]}
                        offset={i - currentIndex}
                    />
                ) : (
                    <Placeholder key={key} />
                )
            );
        }

        items.push(<CarouselSlide key={globalIndex} slide={slides[currentIndex]} offset={0} />);

        for (let i = currentIndex + 1; i <= currentIndex + preload; i += 1) {
            const key = globalIndex + i - currentIndex;
            items.push(
                !carousel.finite || i <= slides.length - 1 ? (
                    <CarouselSlide key={key} slide={slides[i % slides.length]} offset={i - currentIndex} />
                ) : (
                    <Placeholder key={key} />
                )
            );
        }
    }

    return (
        <div
            ref={setCarouselRef}
            className={clsx(cssClass(cssPrefix()), items.length > 0 && cssClass(cssPrefix("with_slides")))}
            style={{
                [`${cssVar(cssPrefix("slides_count"))}`]: items.length,
                [`${cssVar(cssPrefix("spacing_px"))}`]: spacingValue.pixel || 0,
                [`${cssVar(cssPrefix("spacing_percent"))}`]: spacingValue.percent || 0,
                [`${cssVar(cssPrefix("padding_px"))}`]: paddingValue.pixel || 0,
                [`${cssVar(cssPrefix("padding_percent"))}`]: paddingValue.percent || 0,
            }}
        >
            {items}
        </div>
    );
import * as React from "react";

import { clsx, ComponentProps, cssClass, LightboxPropsProvider, makeUseContext, ThumbnailsRef } from "../../index.js";
import { cssPrefix } from "./utils.js";
import { ThumbnailsTrack } from "./ThumbnailsTrack.js";
import { resolveThumbnailsProps } from "./props.js";

export const ThumbnailsContext = React.createContext<ThumbnailsRef | null>(null);

export const useThumbnails = makeUseContext("useThumbnails", "ThumbnailsContext", ThumbnailsContext);

/** Thumbnails plugin component */
export function ThumbnailsContextProvider({ children, ...props }: ComponentProps) {
    const [visible, setVisible] = React.useState(true);
    const containerRef = React.useRef<HTMLDivElement | null>(null);

    const { ref, position } = resolveThumbnailsProps(props.thumbnails);

    const context = React.useMemo(
        () => ({
            visible,
            show: () => setVisible(true),
            hide: () => setVisible(false),
        }),
        [visible]
    );

    React.useImperativeHandle(ref, () => context, [context]);

    return (
        <LightboxPropsProvider {...props}>
            <ThumbnailsContext.Provider value={context}>
                <div ref={containerRef} className={clsx(cssClass(cssPrefix()), cssClass(cssPrefix(`${position}`)))}>
                    {["start", "top"].includes(position) && (
                        <ThumbnailsTrack containerRef={containerRef} visible={visible} />
                    )}
                    <div className={cssClass(cssPrefix("wrapper"))}>{children}</div>
                    {["end", "bottom"].includes(position) && (
                        <ThumbnailsTrack containerRef={containerRef} visible={visible} />
                    )}
                </div>
            </ThumbnailsContext.Provider>
        </LightboxPropsProvider>
    );
}
